pub const BUSINESS_DAY_RULES: [&str; 4] = ["FOLLOWING", "MODIFIED_FOLLOWING", "PRECEDING", "UNADJUSTED"];
pub fn is_leap(year: i32) -> bool { year % 4 == 0 && (year % 100 != 0 || year % 400 == 0) }
pub fn month_length(year: i32, month: i32) -> i32 { if month == 2 && is_leap(year) { 29 } else { [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][(month - 1) as usize] } }
pub fn valid_date(text: &str) -> bool {
    let year: i32 = text[..4].parse().unwrap(); let month: i32 = text[5..7].parse().unwrap(); let day: i32 = text[8..].parse().unwrap();
    (2001..=2099).contains(&year) && (1..=12).contains(&month) && (1..=month_length(year, month)).contains(&day)
}
pub fn day_number(year: i32, month: i32, day: i32) -> i32 {
    let mut number = day - 1;
    for earlier in 2000..year { number += if is_leap(earlier) { 366 } else { 365 }; }
    for earlier in 1..month { number += month_length(year, earlier); }
    number
}
pub fn parse_date(text: &str) -> i32 { day_number(text[..4].parse().unwrap(), text[5..7].parse().unwrap(), text[8..].parse().unwrap()) }
pub fn civil_date(mut number: i32) -> (i32, i32, i32) {
    let mut year = 2000;
    loop { let length = if is_leap(year) { 366 } else { 365 }; if number < length { break; } number -= length; year += 1; }
    let mut month = 1;
    while number >= month_length(year, month) { number -= month_length(year, month); month += 1; }
    (year, month, number + 1)
}
pub fn format_date(number: i32) -> String { let (year, month, day) = civil_date(number); format!("{year:04}-{month:02}-{day:02}") }
pub struct Calendar { holidays: HashSet<i32> }
impl Calendar {
    pub fn new(holidays: impl IntoIterator<Item = i32>) -> Self { Self { holidays: holidays.into_iter().collect() } }
    pub fn business(&self, day: i32) -> bool { (day + 5).rem_euclid(7) < 5 && !self.holidays.contains(&day) }
    pub fn following(&self, mut day: i32) -> i32 { while !self.business(day) { day += 1; } day }
    pub fn preceding(&self, mut day: i32) -> i32 { while !self.business(day) { day -= 1; } day }
    pub fn adjust(&self, day: i32, rule: &str) -> i32 {
        match rule {
            "FOLLOWING" => self.following(day), "PRECEDING" => self.preceding(day),
            "MODIFIED_FOLLOWING" => { let next = self.following(day); if civil_date(next).1 != civil_date(day).1 { self.preceding(day) } else { next } }
            _ => day,
        }
    }
    pub fn move_days(&self, mut day: i32, count: i32) -> i32 {
        let direction = if count < 0 { -1 } else { 1 }; let mut remaining = if count < 0 { -count } else { count };
        while remaining > 0 { day += direction; if self.business(day) { remaining -= 1; } }
        day
    }
}
pub const DAY_COUNTS: [&str; 5] = ["30/360", "30E/360", "ACT/360", "ACT/365F", "ACT/ACT"];
pub fn year_fraction(convention: &str, mut start: i32, end: i32) -> (i64, i64) {
    let (mut y1, m1, mut d1) = civil_date(start); let (y2, m2, mut d2) = civil_date(end);
    match convention {
        "30/360" | "30E/360" => {
            if convention == "30/360" {
                let february = m1 == 2 && d1 == month_length(y1, 2);
                if february && m2 == 2 && d2 == month_length(y2, 2) { d2 = 30; }
                if february { d1 = 30; }
                if d2 == 31 && d1 >= 30 { d2 = 30; }
                if d1 == 31 { d1 = 30; }
            } else { d1 = d1.min(30); d2 = d2.min(30); }
            ((360 * (y2 - y1) + 30 * (m2 - m1) + d2 - d1) as i64, 360)
        }
    }
}
pub const BP: f64 = 0.0001;
pub fn bisection(mut function: impl FnMut(f64) -> f64, mut low: f64, mut high: f64, target: f64) -> f64 {
    for _ in 0..80 { let middle = (low + high) / 2.0; if function(middle) > target { low = middle; } else { high = middle; } }
    (low + high) / 2.0
}
#[derive(Clone, Default)]
pub struct Risk { pub macaulay: f64, pub modified: f64, pub convexity: f64, pub dv01: f64 }
#[derive(Clone)]
pub struct YieldPricer { pub flows: Vec<i64>, pub fraction: f64, pub frequency: i32, pub outstanding: i64 }
impl YieldPricer {
    fn values(&self, rate: f64) -> Vec<f64> {
        let first = 1.0 + self.fraction * rate / self.frequency as f64; let growth = 1.0 + rate / self.frequency as f64;
        let mut factor = 1.0; let mut values = Vec::new();
        for &flow in &self.flows { values.push(flow as f64 / (first * factor)); factor *= growth; }
        values
    }
    pub fn dirty(&self, rate: f64) -> f64 { let mut total = 0.0; for value in self.values(rate) { total += value; } total * 100.0 / self.outstanding as f64 }
    pub fn solve(&self, target: f64) -> f64 { bisection(|rate| self.dirty(rate), 0.0, 1.0, target) }
    pub fn in_range(&self, target: f64) -> bool { self.dirty(0.0) > target && target > self.dirty(1.0) }
    pub fn risk(&self, rate: f64) -> Risk {
        let frequency = self.frequency as f64; let growth = 1.0 + rate / frequency;
        let (mut total, mut weighted, mut curvature) = (0.0, 0.0, 0.0);
        for (index, value) in self.values(rate).into_iter().enumerate() { let years = (index as f64 + self.fraction) / frequency; total += value; weighted += years * value; curvature += years * (years + 1.0 / frequency) * value; }
        let macaulay = weighted / total;
        Risk { macaulay, modified: macaulay / growth, convexity: curvature / (total * growth * growth), dv01: (self.dirty(rate - BP) - self.dirty(rate + BP)) / 2.0 }
    }
}
pub fn coupon_schedule(issue: i32, maturity: i32, frequency: i32, eom: bool, long: bool) -> Vec<i32> {
    let (year, month, day) = civil_date(maturity); let eom = eom && day == month_length(year, month);
    let mut dates = Vec::new(); let mut boundary = maturity;
    while boundary > issue {
        dates.push(boundary);
        let index = year * 12 + month - 1 - (12 / frequency) * dates.len() as i32;
        let y = index / 12; let m = index % 12 + 1;
        boundary = day_number(y, m, if eom { month_length(y, m) } else { day.min(month_length(y, m)) });
    }
    if long && boundary != issue && dates.len() >= 2 { dates.pop(); }
    dates.push(issue); dates.reverse(); dates
}
